/** Metadata for a key, or NULL when we have none recorded. */
static inline const yame_assetinfo_t *yame_assetinfo_find(const char *key) {
    if (!key) return NULL;
    for (const yame_assetinfo_t *k = YAME_ASSETINFO; k->key; ++k) {
        const char *a = k->key, *b = key;
        while (*a && *b) {
            char ca = *a, cb = *b;
            if (ca >= 'A' && ca <= 'Z') ca = (char)(ca - 'A' + 'a');
            if (cb >= 'A' && cb <= 'Z') cb = (char)(cb - 'A' + 'a');
            if (ca != cb) break;
            ++a; ++b;
        }
        if (!*a && !*b) return k;
    }
    return NULL;
}

/** Is `key` part of `collection`'s recommended selection? */
static inline int yame_assetinfo_recommended(const char *key,
                                          const char *collection) {
    const yame_assetinfo_t *k = yame_assetinfo_find(key);
    if (!k || !k->recommend || !*k->recommend || !collection) return 0;

    size_t want = 0;
    while (collection[want]) ++want;

    const char *p = k->recommend;
    while (*p) {
        const char *comma = p;
        while (*comma && *comma != ',') ++comma;
        size_t len = (size_t)(comma - p);
        if (len == want) {
            size_t i = 0;
            while (i < len && p[i] == collection[i]) ++i;
            if (i == len) return 1;
        }
        if (!*comma) break;
        p = comma + 1;
    }
    return 0;
}

